import json
from pathlib import Path

base = Path('/app/data')

route = json.loads((base / 'route.json').read_text())
preferences = json.loads((base / 'preferences.json').read_text())
local_pref = json.loads((base / 'local_pref.json').read_text())

route_events_path = base / 'route_events.json'
route_events = json.loads(route_events_path.read_text()) if route_events_path.exists() else []

possible_solutions = json.loads((base / 'possible_solutions.json').read_text())

# Build preference graph
pref_graph = {}
for k, v in preferences.items():
    try:
        a = int(k)
    except ValueError:
        continue
    b = v.get('prefer_via')
    if b is None:
        continue
    pref_graph.setdefault(a, set()).add(int(b))

# Detect cycle in preference graph
visited = set()
visiting = set()
cycle = None

def dfs(node, path):
    global cycle
    nonlocal_cycle = None
    visiting.add(node)
    path.append(node)
    for nxt in pref_graph.get(node, []):
        if cycle is not None:
            break
        if nxt in visiting:
            # capture cycle segment
            idx = path.index(nxt)
            nonlocal_cycle = path[idx:].copy()
            break
        if nxt not in visited:
            dfs(nxt, path)
            if cycle is not None:
                break
            if nonlocal_cycle is not None:
                break
    path.pop()
    visiting.discard(node)
    visited.add(node)
    if nonlocal_cycle is not None:
        return nonlocal_cycle
    return None

for node in list(pref_graph.keys()):
    if node in visited:
        continue
    c = dfs(node, [])
    if c:
        cycle = c
        break

oscillation_detected = cycle is not None
oscillation_cycle = cycle or []
affected_ases = sorted(set(oscillation_cycle)) if oscillation_cycle else []

# Detect route leaks based on route_events and valley-free rule
route_leaks = []
for ev in route_events:
    src_type = ev.get('source_type')
    dst_type = ev.get('destination_type')
    if src_type in {'provider', 'peer'} and dst_type in {'provider', 'peer'}:
        route_leaks.append({
            'leaker_as': ev.get('advertiser_asn'),
            'source_as': ev.get('source_asn'),
            'destination_as': ev.get('destination_asn'),
            'source_type': src_type,
            'destination_type': dst_type,
        })

route_leak_detected = len(route_leaks) > 0

# Solution evaluation heuristics

def resolves_oscillation(solution: str) -> bool:
    s = solution.lower()
    if 'disable hub peering' in s:
        return True
    if 'stop preferring routes via hub2' in s:
        return True
    if 'update routing preference' in s and 'hub1' in s:
        return True
    if 'route preference hierarchy' in s:
        return True
    if 'hub routing intent' in s and 'hub-to-hub' in s and 'virtual wan' in s:
        return True
    return False


def resolves_route_leak(solution: str) -> bool:
    s = solution.lower()
    if 'disable hub peering' in s:
        return True
    if 'no-export' in s and 'provider routes' in s and 'peer' in s:
        return True
    if 'export policy' in s and 'provider routes' in s and 'peer' in s:
        return True
    if 'hub routing intent' in s and 'hub-to-hub' in s and 'virtual wan' in s:
        return True
    return False

solution_results = {}
for sol in possible_solutions:
    solution_results[sol] = {
        'oscillation_resolved': resolves_oscillation(sol),
        'route_leak_resolved': resolves_route_leak(sol),
    }

result = {
    'oscillation_detected': oscillation_detected,
    'oscillation_cycle': oscillation_cycle,
    'affected_ases': affected_ases,
    'route_leak_detected': route_leak_detected,
    'route_leaks': route_leaks,
    'solution_results': solution_results,
}

out_path = Path('/app/output/oscillation_report.json')
out_path.parent.mkdir(parents=True, exist_ok=True)
out_path.write_text(json.dumps(result, indent=2))

print(out_path)
PY"}

